// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product} from "../src/Product.sol";

contract InvMutTest is Test {
    Product c;
    function setUp() public { c = new Product(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));

        // oracle() observed from the test contract itself
        address oracleFromSelf = address(c.oracle());

        // oracle() observed from an arbitrary external caller
        vm.prank(caller);
        address oracleFromCaller = address(c.oracle());

        // Rule: oracle() is caller-independent — every caller sees the same oracle address.
        assertTrue(oracleFromSelf == oracleFromCaller);
    }
}
